use super::GisTerrainSnapshot;
use store::{ArtifactSqliteSnapshot,sqlite_snapshot::{SqliteDatabaseLimits,SqliteSnapshotControl,SnapshotEncoding,export_sqlite_database,import_sqlite_database}};
fn fixture()->(serde_json::Value,GisTerrainSnapshot){let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let child=&f["child"];let target=&child["target"];let dialect=&target["dialect"];let s=|v:&serde_json::Value|v.as_str().unwrap().to_owned();let value=GisTerrainSnapshot{exaggeration:1.5,imported_features_json:s(&f["importedFeaturesJson"]),mesh:Some(store::ArtifactChild::new(s(&child["childId"]),store::os_io::ArtifactRef{artifact_id:s(&target["artifactId"]),dialect:store::os_io::ArtifactDialect{artifact_kind:s(&dialect["artifactKind"]),standard:s(&dialect["standard"]),subset:s(&dialect["subset"])}}))};(f,value)}
#[test]
fn sqlite_snapshot_gis_terrain_all_ieee_words_and_independent_sql(){use std::{io::Write,process::{Command,Stdio}};let(f,mut value)=fixture();let limits=SqliteDatabaseLimits::default();for word in f["words"].as_array().unwrap(){value.exaggeration=f64::from_bits(u64::from_str_radix(word.as_str().unwrap(),16).unwrap());let database=value.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();let restored=GisTerrainSnapshot::from_sqlite_database(&database,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();assert_eq!(restored.exaggeration.to_bits(),value.exaggeration.to_bits());assert_eq!(restored.imported_features_json,value.imported_features_json);assert_eq!(restored.mesh,value.mesh);let bytes=export_sqlite_database(&database,limits,&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(d.query('PRAGMA integrity_check').get().integrity_check!=='ok'||d.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');d.query('UPDATE gis_terrain_parameters SET imported_features_json=?').run('independent semantic edit');await Bun.write(Bun.stdout,d.serialize());d.close();";let mut p=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();p.stdin.take().unwrap().write_all(&bytes).unwrap();let output=p.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));let edited=GisTerrainSnapshot::from_sqlite_database(&import_sqlite_database(&output.stdout,limits,&mut |_|true).unwrap(),&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();assert_eq!(edited.exaggeration.to_bits(),value.exaggeration.to_bits());assert_eq!(edited.imported_features_json,"independent semantic edit");}}
#[test]
fn sqlite_snapshot_gis_terrain_complete_native_record_and_actual_erased_provider(){let(f,mut value)=fixture();let limits=SqliteDatabaseLimits::default();let provider=<GisTerrainSnapshot as ArtifactSqliteSnapshot>::sqlite_codec();let dialect=store::os_io::ArtifactDialect{artifact_kind:"s.gis.gisterrain".into(),standard:"1".into(),subset:"*".into()};for word in f["words"].as_array().unwrap(){value.exaggeration=f64::from_bits(u64::from_str_radix(word.as_str().unwrap(),16).unwrap());let expected=value.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=match encoding{SnapshotEncoding::Binary=>store::os_io::IoPayload::Binary(store::ArtifactPack::encode_pack(&value)),SnapshotEncoding::Text=>store::os_io::IoPayload::Text(store::ArtifactDsl::print_dsl(&value))};assert_eq!((provider.export)(crate::GIS_3D_TERRAIN_SCHEMA,&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap().value,expected);let restored=(provider.import)(crate::GIS_3D_TERRAIN_SCHEMA,&dialect,expected.clone(),encoding,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap().value;assert_eq!((provider.export)(crate::GIS_3D_TERRAIN_SCHEMA,&dialect,&restored,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap().value,expected);}}}
#[test]
fn sqlite_snapshot_gis_terrain_exact_profile_and_resource_admission(){let(_,value)=fixture();let limits=SqliteDatabaseLimits::default();let database=value.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();let dialect=store::os_io::ArtifactDialect{artifact_kind:"s.gis.gisterrain".into(),standard:"1".into(),subset:"*".into()};assert!(value.validate_sqlite_snapshot_subset(&dialect,&database,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_ok());let mut wrong=dialect;wrong.subset="unknown".into();assert!(value.validate_sqlite_snapshot_subset(&wrong,&database,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());for limits in[SqliteDatabaseLimits{max_rows:2,..limits},SqliteDatabaseLimits{max_value_bytes:16,..limits}]{assert!(value.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());assert!(GisTerrainSnapshot::from_sqlite_database(&database,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());}assert!(value.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|false,limits)).is_err());assert!(GisTerrainSnapshot::from_sqlite_database(&database,&mut SqliteSnapshotControl::new(&mut |_|false,limits)).is_err());}

#[semio_framework_async_macros::async_test]
async fn sqlite_snapshot_gisterrain_real_declaration_public_typed_io() {
    use store::io::{ArtifactDialect,io_mechanism::{io_export_sqlite_snapshot,io_import_sqlite_snapshot,io_route,io_run_with_snapshot_control}};
    semio_framework_plugin::Plugin::<semio_framework_plugin::app::NoPluginApp>::builder("gis").label("GIS SQLite declaration").version("0.0.1").package_id("semio:gis").artifact(crate::declaration().unwrap()).try_build().unwrap();
    let dialect=ArtifactDialect{artifact_kind:"s.gis.gisterrain".into(),standard:"1".into(),subset:"*".into()};
    let (_,snapshot)=fixture();
    let limits=SqliteDatabaseLimits::default();
    let expected=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();
    let sqlite=ArtifactDialect::from(store::io_schema::SQLITE_SNAPSHOT);
    let export=io_route(&dialect,&sqlite,1).await.unwrap().value;
    let import=io_route(&sqlite,&dialect,1).await.unwrap().value;
    for encoding in[SnapshotEncoding::Text,SnapshotEncoding::Binary]{
        let mut phases=Vec::new();
        let bytes=io_export_sqlite_snapshot(&dialect,&snapshot,encoding,limits,&mut |p|{phases.push(p.phase);true}).await.unwrap().value;
        let restored=io_import_sqlite_snapshot::<GisTerrainSnapshot>(&dialect,&bytes,limits,&mut |_|true).await.unwrap().value;
        assert_eq!(restored.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap(),expected);
        assert!(!phases.iter().any(|p|matches!(p,store::sqlite_snapshot::SqliteSnapshotPhase::EncodeNative|store::sqlite_snapshot::SqliteSnapshotPhase::DecodeNative)));
        let payload=match encoding{SnapshotEncoding::Binary=>store::os_io::IoPayload::Binary(store::ArtifactPack::encode_pack(&snapshot)),SnapshotEncoding::Text=>store::os_io::IoPayload::Text(store::ArtifactDsl::print_dsl(&snapshot))};
        let file=io_run_with_snapshot_control(&export,payload,limits,&mut |_|true).await.unwrap().value;
        let payload=io_run_with_snapshot_control(&import,file,limits,&mut |_|true).await.unwrap().value;
        let decoded=GisTerrainSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();
        assert_eq!(decoded.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap(),expected);
        <GisTerrainSnapshot as ArtifactSqliteSnapshot>::retire_sqlite_snapshot(decoded);
    }
}

#[test]
fn sqlite_snapshot_gis_terrain_whole_native_controls_admission_and_interior_cancellation(){let(_,mut value)=fixture();value.exaggeration=f64::from_bits(0xfff0000000001234);value.imported_features_json="literal intrinsic text 世界".repeat(10000);let limits=SqliteDatabaseLimits::default();for payload in[store::os_io::IoPayload::Binary(store::ArtifactPack::encode_pack(&value)),store::os_io::IoPayload::Text(store::ArtifactDsl::print_dsl(&value))]{let restored=GisTerrainSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();assert_eq!(restored.exaggeration.to_bits(),value.exaggeration.to_bits());assert_eq!(restored.imported_features_json,value.imported_features_json);assert_eq!(restored.mesh,value.mesh);for limits in[SqliteDatabaseLimits{max_rows:2,..limits},SqliteDatabaseLimits{max_value_bytes:4096,..limits}]{assert!(GisTerrainSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err())}let mut interior=false;assert!(GisTerrainSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |p|{if p.phase==store::sqlite_snapshot::SqliteSnapshotPhase::DecodeNative&&p.completed>=256&&p.completed<p.total{interior=true;false}else{true}},limits)).is_err());assert!(interior);}}
